#!/usr/bin/env bash
# A compact, cached map of this Laravel app: routes, models (with relations), controllers,
# policies, services, view folders and tables. Read it instead of exploring with grep/ls: one
# read of a few hundred tokens replaces a dozen tool calls on every task.
#   repo-map.sh            print the map (regenerated only when the tree changed)
#   repo-map.sh --refresh  force regeneration
# Generated by scripts, never by a model, so it costs nothing to keep current.
set -uo pipefail
ROOT="${CLAUDE_PROJECT_DIR:-$PWD}"
[ -f "$ROOT/artisan" ] || { echo "(not a Laravel project)"; exit 0; }
CACHE="$ROOT/.claude/.cache/repo-map.md"; KEYF="$ROOT/.claude/.cache/repo-map.key"
mkdir -p "$ROOT/.claude/.cache"

# Freshness key: the tracked file list with blob hashes, plus uncommitted changes, for the paths
# the map describes. Without git, file paths + mtimes.
PATHS=(app routes database/migrations resources/views)
if git -C "$ROOT" rev-parse --is-inside-work-tree >/dev/null 2>&1; then
  KEY="$( { git -C "$ROOT" ls-files -s -- "${PATHS[@]}"; git -C "$ROOT" status --porcelain -uall -- "${PATHS[@]}"; } 2>/dev/null | cksum)"
else
  KEY="$(cd "$ROOT" && find "${PATHS[@]}" -type f -printf '%p %T@\n' 2>/dev/null | sort | cksum)"
fi
if [ "${1:-}" != --refresh ] && [ -s "$CACHE" ] && [ "$(cat "$KEYF" 2>/dev/null)" = "$KEY" ]; then cat "$CACHE"; exit 0; fi

rel() { sed "s|^$ROOT/||"; }
classes() { # classes <dir> -> "Name" per PHP file, relative to the dir
  [ -d "$ROOT/$1" ] || return 0
  find "$ROOT/$1" -name '*.php' 2>/dev/null | sed "s|^$ROOT/$1/||; s|\.php$||" | sort | tr '\n' ' '
}
{
  echo "# Repo map (generated $(date +%F) by repo-map.sh — regenerated automatically when files change)"
  echo
  echo "## Models (relations)"
  for f in "$ROOT"/app/Models/*.php; do
    [ -f "$f" ] || continue
    REL="$(grep -oE 'function [a-zA-Z]+\(\)[^{]*:[[:space:]]*(HasMany|HasOne|BelongsTo|BelongsToMany|MorphTo|MorphMany|MorphOne|HasManyThrough|HasOneThrough)' "$f" \
           | sed -E 's/function ([a-zA-Z]+).*:[[:space:]]*([A-Za-z]+)/\1:\2/' | tr '\n' ' ')"
    echo "- $(basename "$f" .php)${REL:+ — $REL}"
  done
  echo
  for d in "app/Http/Controllers" "app/Http/Requests" "app/Policies" "app/Services" "app/Actions" "app/Jobs" "app/Observers" "app/View/Components" "app/Livewire"; do
    C="$(classes "$d")"; [ -n "$C" ] && printf '## %s\n%s\n\n' "$d" "$C"
  done
  echo "## Tables (from migrations)"
  ls "$ROOT"/database/migrations/*.php 2>/dev/null | sed -nE 's/.*create_([a-z0-9_]+)_table\.php$/\1/p' | sort -u | tr '\n' ' '
  echo; echo
  echo "## Routes (grouped by controller: URI prefix → actions)"
  # artisan route:list is exact (includes package routes) but boots the app; fall back to grep.
  if R="$(cd "$ROOT" && timeout 20 php artisan route:list --json --except-vendor 2>/dev/null)" && [ -n "$R" ] && command -v jq >/dev/null; then
    printf '%s' "$R" | jq -r '
      map(. + {ctrl: (.action | sub("^App\\\\Http\\\\Controllers\\\\";"") | split("@")[0]),
               act: (.action | split("@")[1] // "__invoke")})
      | group_by(.ctrl)[]
      | "- \(.[0].ctrl): /\((map(.uri) | min_by(length)) | ltrimstr("/")) → \(map(.act) | unique | join(","))"' | head -60
  else
    grep -hoE "Route::(get|post|put|patch|delete|resource|view|match)\([^;]*" "$ROOT"/routes/*.php 2>/dev/null | cut -c1-120 | sed 's/^/- /' | head -60
  fi
  echo
  echo "## View folders"
  [ -d "$ROOT/resources/views" ] && find "$ROOT/resources/views" -mindepth 1 -maxdepth 2 -type d | rel | sort | tr '\n' ' '
  echo
} > "$CACHE.full" 2>/dev/null
# Trim after writing (piping into `head -c` would SIGPIPE the writer and, with pipefail, fail the
# whole step). The cap keeps the map a cheap read even on large apps.
head -c 6000 "$CACHE.full" > "$CACHE"; rm -f "$CACHE.full"
printf '%s' "$KEY" > "$KEYF"
cat "$CACHE"
